<script>var tm;document.getElementById('ps').oninput=function(){document.getElementById('pid').value='';clearTimeout(tm);var q=this.value.trim(),box=document.getElementById('pr');if(q.length<2){box.innerHTML='';return}tm=setTimeout(function(){fetch('/admin/purchase/api/products?q='+encodeURIComponent(q),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(a){box.innerHTML='';a.slice(0,6).forEach(function(p){var b=document.createElement('button');b.type='button';b.className='g sm';b.style.margin='2px';b.textContent=p.name;b.onclick=function(){document.getElementById('ps').value=p.name;document.getElementById('pid').value=p.id;box.innerHTML=''};box.appendChild(b)})})},250)};</script>@endsection
